D=/dev/ttyMT0; P=/proc; id -u; B=; for b in /data/adb/magisk/busybox /sbin/.magisk/busybox/busybox /data/app/com.topjohnwu.magisk*/lib/arm*/libbusybox.so /system/xbin/busybox /system/bin/busybox; do if [ -x $b ]; then B=$b; echo BB=$b; break; fi; done; [ -e $D ] && echo DEV=ok; if [ -z "$B" ] || [ ! -e $D ]; then exit 0; fi; p=; last=; $B ls -l $P/[0-9]*/fd 2>/dev/null | $B grep -e "^$P/[0-9]*/fd:\$" -e " -> $D\$" | while IFS= read -r l; do case "$l" in $P/*/fd:) [ -z "$p" ] && echo S; p=${l#$P/}; p=${p%/fd:} ;; *" -> $D") if [ "$p" != "$last" ]; then last=$p; echo -n "H $p "; $B tr '\000\n' '  ' < $P/$p/cmdline 2>/dev/null; echo; fi ;; esac; done; echo END
